import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        return
    n = len(s)
    best_start = 0
    max_len = 1

    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(n):
        l1, r1 = expand(i, i)
        if r1 - l1 + 1 > max_len:
            max_len = r1 - l1 + 1
            best_start = l1
        l2, r2 = expand(i, i + 1)
        if r2 - l2 + 1 > max_len:
            max_len = r2 - l2 + 1
            best_start = l2

    print(s[best_start:best_start + max_len])

if __name__ == '__main__':
    solve()

