import sys

def compute_lps(pattern):
    m = len(pattern)
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def solve():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return
    S, P = lines[0], lines[1]
    n, m = len(S), len(P)
    if m > n:
        print('NOT_FOUND')
        return
    lps = compute_lps(P)
    res = []
    i = j = 0
    while i < n:
        if P[j] == S[i]:
            i += 1; j += 1
        if j == m:
            res.append(str(i - j))
            j = lps[j - 1]
        elif i < n and P[j] != S[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    print(' '.join(res) if res else 'NOT_FOUND')

