    static class Pair implements Comparable<Pair> {
        int count;
        char ch;
        Pair(int c, char ch) { this.count = c; this.ch = ch; }
        public int compareTo(Pair o) {
            if (this.count != o.count) return Integer.compare(o.count, this.count);
            return Character.compare(this.ch, o.ch);
        }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        s = s.trim();
        int[] freq = new int[26];
        int maxF = 0;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            freq[c]++;
            if (freq[c] > maxF) maxF = freq[c];
        }
        if (maxF > (s.length() + 1) / 2) {
            System.out.println("IMPOSSIBLE");
            return;
        }
        PriorityQueue<Pair> pq = new PriorityQueue<>();
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) pq.offer(new Pair(freq[i], (char)('a' + i)));
        }
        StringBuilder sb = new StringBuilder();
        Pair prev = null;
        while (!pq.isEmpty()) {
            Pair curr = pq.poll();
            sb.append(curr.ch);
            curr.count--;
            if (prev != null && prev.count > 0) pq.offer(prev);
            prev = curr;
        }
        System.out.println(sb.toString());
    }
}

