#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int R, C;
vector<vector<string>> categories;
vector<string> result;

void backtrack(int r, string curr) {
    if (r == R) {
        result.push_back(curr);
        return;
    }
    for (int c = 0; c < C; c++) {
        string next_curr = curr.empty() ? categories[r][c] : curr + " " + categories[r][c];
        backtrack(r + 1, next_curr);
    }
}

int main() {
    if (!(cin >> R >> C)) return 0;
    categories.assign(R, vector<string>(C));
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) cin >> categories[r][c];
    }
    backtrack(0, "");
    sort(result.begin(), result.end());
    for (const string& s : result) cout << s << '\n';
    return 0;
}
